  mcp_tab: ["MCP", "MCP"], mcp_src_tab: ["MCP kaynakları", "MCP sources"], mcp_src_tab_logs: ["Log kaynakları", "Log sources"],
  mcp_keys_intro: ["Watchover'ı MCP sunucusu olarak açar: Claude, Cursor ya da kendi ajanlarınız loglar, panolar, sunucu detayı, eşikler, anomaliler, izler, iş akışları, envanter ve aksiyonlar için araç çağırır. Her anahtar bir hesaba (o hesabın gördüğü kadar) ya da bir ekibe (yalnız ekibin sunucuları) bağlıdır, varsayılan salt okunurdur; yazma araçları yalnız \"yazma\" izniyle. Kişisel veri maskelenir, her çağrı denetim kaydına düşer. Adres: <arayüz>/api/mcp (doğrudan 8501'de /mcp da olur).", "Opens Watchover as an MCP server: Claude, Cursor or your own agents call tools for logs, dashboards, host detail, thresholds, anomalies, traces, business flows, inventory and actions. Each key is bound to an account (sees what that account sees) or a team (that team's hosts only) and is read-only by default; write tools only with the \"write\" permission. Personal data is masked and every call is audited. Address: <interface>/api/mcp (also /mcp directly on 8501)."],
  mcp_key_new: ["Yeni MCP anahtarı", "New MCP key"], mcp_key_name: ["Anahtar adı (ör. cursor-ayse)", "Key name (e.g. cursor-jane)"], mcp_kind_user: ["Hesabıma bağlı", "Bound to my account"], mcp_kind_team: ["Ekibe bağlı", "Bound to a team"],
  mcp_write: ["yazma izni", "write permission"], mcp_write_warn: ["Yazma: aksiyon açma, anomaliyi onaylama ve eşik tanımlama araçları da açılır (yine anahtarın kapsamı ve izinleriyle).", "Write: also opens create action, acknowledge anomaly and set threshold (still within the key's scope and permissions)."],
  mcp_read_note: ["Salt okunur: yalnız okuma araçları.", "Read-only: read tools only."], mcp_keys: ["MCP anahtarları", "MCP keys"], mcp_keys_none: ["Henüz anahtar yok.", "No keys yet."],
  mcp_bound: ["Bağlı olduğu", "Bound to"], mcp_access: ["Erişim", "Access"], mcp_rw: ["okuma + yazma", "read + write"], mcp_ro: ["salt okunur", "read-only"], mcp_last_used: ["Son kullanım", "Last used"], mcp_calls: ["çağrı", "calls"],
  mcp_created: ["Oluşturuldu", "Created"], mcp_revoke: ["İptal et", "Revoke"], mcp_revoked: ["iptal", "revoked"], mcp_tools: ["Araçlar", "Tools"], mcp_tools_n: ["araç", "tools"], mcp_what: ["Ne yapar", "What it does"], mcp_perm: ["Gereken izin", "Permission"],
  mcp_audit: ["MCP denetim kaydı", "MCP audit log"], mcp_audit_none: ["Henüz çağrı yok.", "No calls yet."], mcp_when: ["Zaman", "When"], mcp_who: ["Kim", "Who"], mcp_tool: ["Araç", "Tool"],
  mcp_key_once: ["MCP anahtarı (bir kez gösterilir)", "MCP key (shown once)"], mcp_key_once_help: ["Anahtarı şimdi kopyalayın; yalnız özeti saklanır, tekrar gösterilemez. İstemci ayarı:", "Copy the key now; only its hash is stored and it cannot be shown again. Client configuration:"],
  mcp_src_intro: ["Dış MCP sunucularından veri çekin: araçlarını listeleyin, bir aracı sabit argümanlarla aralıkla çağırın; sonuç log satırı (kaynak adıyla, JSON alanları korunur), envanter satırı (CMDB) ya da ITSM kaydı olarak alınır. Yalnız streamable HTTP ve HTTP+SSE (konteynerde stdio yok). Token / başlık diğer sırlar gibi şifreli saklanır. Ekibe ait kaynak yalnız ekibin sunucularına yazar.", "Pull data from external MCP servers: list their tools and call one with fixed arguments on an interval; the result is ingested as log lines (under a source name, JSON fields kept), inventory rows (CMDB) or ITSM tickets. Streamable HTTP and HTTP+SSE only (no stdio in the container). Tokens / headers are stored encrypted like other secrets. A team's source writes only to the team's hosts."],
  mcp_src_add: ["MCP kaynağı ekle", "Add MCP source"], mcp_src_none: ["Henüz MCP kaynağı yok.", "No MCP sources yet."], mcp_src_url_help: ["MCP uç noktası, ör. https://sunucu/mcp ya da SSE için https://sunucu/sse", "The MCP endpoint, e.g. https://server/mcp or https://server/sse for SSE"],
  mcp_transport: ["Taşıma", "Transport"], mcp_auth_header: ["Özel başlık", "Custom header"], mcp_header_name: ["Başlık adı", "Header name"], mcp_timeout: ["Zaman sınırı (sn)", "Time limit (s)"], mcp_max_kb: ["Yanıt sınırı (KB)", "Answer limit (KB)"],
  mcp_assist_tools: ["Watchover'a sor'un kullanabileceği araçlar", "Tools \"Ask Watchover\" may use"], mcp_assist_help: ["Virgülle; yalnız okuma: readOnlyHint=false ya da destructiveHint=true bildiren araç hiç çağrılmaz. Soru maskelenerek gönderilir, cevaplar [M1] diye kaynak gösterilir.", "Comma separated; read-only: a tool declaring readOnlyHint=false or destructiveHint=true is never called. The question is sent masked, answers are cited as [M1]."],
