  mcp_target: ["Hedef", "Target"], mcp_target_logs: ["Log satırları", "Log lines"], mcp_target_inventory: ["Envanter (CMDB)", "Inventory (CMDB)"], mcp_target_itsm: ["ITSM kayıtları", "ITSM tickets"],
