  mcp_mapping_help_logs: ["İsteğe bağlı: {\"items\": \"data.rows\", \"ts\": \"time\", \"host\": \"node\", \"msg\": \"text\"}", "Optional: {\"items\": \"data.rows\", \"ts\": \"time\", \"host\": \"node\", \"msg\": \"text\"}"],
