  au_ph_failed: ["Başarısız", "Failed"], au_ph_rolled_back: ["Geri alındı", "Rolled back"], au_ph_escalated: ["Devredildi", "Escalated"], au_ph_dismissed: ["Gerek yok", "Not needed"], au_ph_suppressed: ["Bastırıldı", "Suppressed"],
  au_off_title: ["Otomasyon kapalı", "Automation is off"], au_off_lead: ["Açıldığında log uyarıları, eşik aşımları, anomaliler ve olaylar kanıtıyla birlikte vaka olur ve burada \"önce insan gereken\" sırasıyla listelenir. Önce yalnız vakalar ve rehberli mod gelir; sistem hiçbir komutu kendisi çalıştırmaz.", "When on, log alerts, threshold breaches, anomalies and incidents become cases with their evidence, listed here by \"needs a person now\". It starts with cases and guided mode only; the system runs no command by itself."],
  au_off_enable: ["Sistem › Durum'dan etkinleştir", "Enable under System › Status"],
  au_mode_title: ["Eylem ajanı (otomasyon)", "Action agent (automation)"], au_mode_lead: ["Loglardan vaka açar, adım adım rehberlik eder; güven kazandıkça otomatikleşir. Güncellemeden sonra kapalı gelir.", "Opens cases from the logs and guides step by step; automates as it earns trust. Off after an upgrade."],
  au_mode_off: ["Kapalı", "Off"], au_mode_guided: ["Rehberli", "Guided"], au_mode_other: ["Diğer", "Other"], au_mode_now: ["Şu an: {mode} · anahtar saklama: {custody}", "Now: {mode} · key custody: {custody}"],
  au_mode_note: ["Rehberli: vakalar açılır, komut kişiye gösterilir, sistem çalıştırmaz. Onaylı ve üstü sonraki sürümlerde, kalan risk notu ve imza anahtarlarıyla açılır. Değiştirmek kimlik doğrulaması ister; kapatmak istemez.", "Guided: cases open, commands are shown to people, the system runs nothing. Approved and above come in later releases with the residual-risk note and signing keys. Changing it needs a step-up; switching off does not."],
  au_killed: ["Otomasyon durduruldu", "Automation stopped"], au_stepup_code: ["E-postadaki kod", "Code from the e-mail"], au_stepup_password: ["Parolanızla doğrulayın", "Confirm with your password"],
  au_stepup_verify: ["Doğrula", "Verify"], au_stepup_weak: ["Parola ile doğrulandı (zayıf adım doğrulaması).", "Verified with the password (weak step-up)."],
  au_kill_banner: ["Otomasyon durduruldu: {scope} · {by} · {ts} · {reason}", "Automation stopped: {scope} · {by} · {ts} · {reason}"],
  au_act_title: ["Eylem ajanları", "Action agents"],
  au_act_lead: ["Sunuculardaki eylem ajanları (wo-agent act). Bir ajan ilk bağlandığında anahtarının parmak izini sunucu konsoluna ve günlüğe yazar; aynı parmak izini buraya yapıştırıp onaylayana kadar o sunucuya hiçbir iş gönderilmez.", "The action agents on the servers (wo-agent act). On first contact an agent prints its key fingerprint on the server console and journal; until the same fingerprint is pasted and confirmed here, no job goes to that server."],
  au_act_off: ["Otomasyon kapalıyken eylem ajanları uykuda bekler: yalnız ara sıra merhaba der, iş almaz.", "While automation is off the action agents stay dormant: they only say hello now and then and take no job."],
  au_act_none: ["Henüz merhaba diyen eylem ajanı yok.", "No action agent has said hello yet."],
