  au_act_confirm: ["Eylem anahtarını onayla", "Confirm the action key"], au_act_paste: ["Sunucudaki parmak izi (SHA256:…)", "Fingerprint on the server (SHA256:…)"],
  au_act_confirmed: ["Onaylı", "Confirmed"], au_act_unconfirmed: ["Onay bekliyor", "Awaiting confirmation"], au_act_revoked: ["İptal edildi", "Revoked"],
  au_act_revoke: ["Anahtarı iptal et", "Revoke the key"], au_act_mismatch: ["Parmak izi ajanın bildirdiği anahtarla uyuşmuyor: onaylanmadı.", "The fingerprint does not match the key the agent reported: not confirmed."],
