  an_st_learning: ["Öğrenme kayıtları", "Learning records"], an_learn_title: ["Öğrenme modu: her sunucu ilk {d} gün normalini öğrenir", "Learning mode: each host learns its normal for {d} days"],
  an_learn_lead: ["Bu sürede istatistiksel bulgular 'öğrenme kaydı' olarak saklanır; bildirim gitmez, zile düşmez. Sonrasında aynı gün ve saatin geçmiş haftaları da normal sayılır (pazartesi sabahı yoğunluğu, gece batch'leri). CPU / bellek / disk eşikleri ve operasyon ekranı ilk dakikadan anlık çalışır.", "Meanwhile statistical findings are kept as learning records: no notification, not in the bell. Afterwards the same weekday and hour of past weeks also count as normal (Monday-morning peaks, nightly batches). CPU / memory / disk thresholds and the operations views work from the first minute."],
  an_learn_shadow: ["{n} öğrenme kaydı", "{n} learning records"], an_learn_done: ["öğrenildi", "learned"], an_learn_done_n: ["{n} sunucu öğrenmeyi tamamladı.", "{n} hosts finished learning."],
